class WordDictionary:
    def __init__(self):
        self.root = {}                 # char → child dict; '$' marks a word end

    def addWord(self, word):
        node = self.root
        for c in word:
            node = node.setdefault(c, {})
        node['$'] = True

    def search(self, word):
        def dfs(node, i):
            if i == len(word):
                return '$' in node
            c = word[i]
            if c == '.':               # fork into every child
                return any(dfs(child, i + 1) for key, child in node.items() if key != '$')
            return c in node and dfs(node[c], i + 1)

        return dfs(self.root, 0)

class WordDictionary:
    def __init__(self):
        self.words = set()

    def addWord(self, word):
        self.words.add(word)

    def search(self, word):            # compare against every stored word
        return any(len(w) == len(word) and all(p in ('.', c) for p, c in zip(word, w))
                   for w in self.words)

P24-implement-trie-prefix-tree:
class TrieNode:
    def __init__(self):
        self.children = [None] * 26
        self.is_end = False


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for c in word:
            i = ord(c) - 97
            if not node.children[i]:
                node.children[i] = TrieNode()
            node = node.children[i]
        node.is_end = True

    def _walk(self, s):
        node = self.root
        for c in s:
            node = node.children[ord(c) - 97]
            if not node:
                return None
        return node

    def search(self, word):
        node = self._walk(word)
        return bool(node and node.is_end)

    def startsWith(self, prefix):
        return self._walk(prefix) is not None

